#!/usr/bin/env python3
"""
System & Hardware Controller for MintPilot on Linux Mint
Provides native control over audio, display brightness, battery,
networking (Wi-Fi), bluetooth, processes, and power states.
"""

import os
import re
import shutil
import subprocess
from typing import Dict, Any, List, Optional


class SystemController:
    """Controls Linux Mint hardware and system services."""

    def __init__(self):
        self._has_pactl = shutil.which("pactl") is not None
        self._has_brightnessctl = shutil.which("brightnessctl") is not None
        self._has_nmcli = shutil.which("nmcli") is not None
        self._has_bluetoothctl = shutil.which("bluetoothctl") is not None
        self._has_upower = shutil.which("upower") is not None

    # ==================== AUDIO / VOLUME ====================

    def get_volume(self) -> Dict[str, Any]:
        """Gets the current master volume and mute state."""
        if not self._has_pactl:
            return {"error": "pactl not available"}

        try:
            res = subprocess.run(
                ["pactl", "get-sink-volume", "@DEFAULT_SINK@"],
                capture_output=True, text=True, check=True
            )
            match = re.search(r"(\d+)%", res.stdout)
            vol = int(match.group(1)) if match else None

            mute_res = subprocess.run(
                ["pactl", "get-sink-mute", "@DEFAULT_SINK@"],
                capture_output=True, text=True, check=True
            )
            is_muted = "yes" in mute_res.stdout.lower()

            return {"volume_percent": vol, "muted": is_muted, "status": "success"}
        except Exception as e:
            return {"error": str(e), "status": "failed"}

    def set_volume(self, percent: int) -> Dict[str, Any]:
        """Sets the master volume (0 to 150%)."""
        if not self._has_pactl:
            return {"error": "pactl not available"}
        try:
            percent = max(0, min(150, int(percent)))
            subprocess.run(
                ["pactl", "set-sink-volume", "@DEFAULT_SINK@", f"{percent}%"],
                check=True, capture_output=True
            )
            return {"status": "success", "new_volume": percent}
        except Exception as e:
            return {"error": str(e), "status": "failed"}

    def toggle_mute(self, state: Optional[bool] = None) -> Dict[str, Any]:
        """Toggles or sets the audio mute state."""
        if not self._has_pactl:
            return {"error": "pactl not available"}
        try:
            arg = "toggle" if state is None else ("1" if state else "0")
            subprocess.run(
                ["pactl", "set-sink-mute", "@DEFAULT_SINK@", arg],
                check=True, capture_output=True
            )
            return self.get_volume()
        except Exception as e:
            return {"error": str(e), "status": "failed"}

    # ==================== DISPLAY BRIGHTNESS ====================

    def get_brightness(self) -> Dict[str, Any]:
        """Gets current display brightness percentage."""
        if self._has_brightnessctl:
            try:
                res = subprocess.run(
                    ["brightnessctl", "info"],
                    capture_output=True, text=True, check=True
                )
                match = re.search(r"\((\d+)%\)", res.stdout)
                val = int(match.group(1)) if match else None
                return {"brightness_percent": val, "status": "success"}
            except Exception as e:
                return {"error": str(e), "status": "failed"}
        return {"error": "brightnessctl not installed", "status": "failed"}

    def set_brightness(self, percent: int) -> Dict[str, Any]:
        """Sets display brightness (1 to 100%)."""
        percent = max(1, min(100, int(percent)))
        if self._has_brightnessctl:
            try:
                subprocess.run(
                    ["brightnessctl", "set", f"{percent}%"],
                    check=True, capture_output=True
                )
                return {"status": "success", "brightness_percent": percent}
            except Exception as e:
                return {"error": str(e), "status": "failed"}
        return {"error": "brightnessctl not available"}

    # ==================== BATTERY & POWER ====================

    def get_battery_status(self) -> Dict[str, Any]:
        """Returns battery charge percentage, state (charging/discharging), and health."""
        if not self._has_upower:
            return {"error": "upower not available"}

        try:
            enum_res = subprocess.run(
                ["upower", "-e"], capture_output=True, text=True, check=True
            )
            bat_path = None
            for line in enum_res.stdout.splitlines():
                if "battery" in line:
                    bat_path = line.strip()
                    break

            if not bat_path:
                return {"status": "desktop_no_battery", "percentage": 100, "state": "AC"}

            info_res = subprocess.run(
                ["upower", "-i", bat_path], capture_output=True, text=True, check=True
            )
            info = {}
            for line in info_res.stdout.splitlines():
                if ":" in line:
                    k, v = line.split(":", 1)
                    info[k.strip()] = v.strip()

            return {
                "percentage": info.get("percentage"),
                "state": info.get("state"),
                "time_to_empty": info.get("time to empty"),
                "time_to_full": info.get("time to full"),
                "status": "success"
            }
        except Exception as e:
            return {"error": str(e), "status": "failed"}

    def execute_power_action(self, action: str) -> Dict[str, Any]:
        """Executes sleep, lock, reboot, or poweroff."""
        action = action.lower().strip()
        commands = {
            "lock": ["cinnamon-screensaver-command", "-l"] if shutil.which("cinnamon-screensaver-command") else ["xdg-screensaver", "lock"],
            "suspend": ["systemctl", "suspend"],
            "sleep": ["systemctl", "suspend"],
            "reboot": ["systemctl", "reboot"],
            "poweroff": ["systemctl", "poweroff"],
            "shutdown": ["systemctl", "poweroff"]
        }

        if action not in commands:
            return {"error": f"Unknown power action '{action}'. Valid: lock, suspend, reboot, poweroff"}

        try:
            subprocess.run(commands[action], check=True)
            return {"status": "success", "action_triggered": action}
        except Exception as e:
            return {"error": str(e), "status": "failed"}

    # ==================== WI-FI & NETWORKING ====================

    def get_network_status(self) -> Dict[str, Any]:
        """Gets active Wi-Fi and Ethernet connections."""
        if not self._has_nmcli:
            return {"error": "nmcli not available"}
        try:
            con_res = subprocess.run(
                ["nmcli", "-t", "-f", "NAME,TYPE,DEVICE,STATE", "connection", "show", "--active"],
                capture_output=True, text=True, check=True
            )
            connections = []
            for line in con_res.stdout.splitlines():
                if line.strip():
                    parts = line.split(":")
                    if len(parts) >= 3:
                        connections.append({
                            "name": parts[0],
                            "type": parts[1],
                            "device": parts[2],
                            "state": parts[3] if len(parts) > 3 else "active"
                        })

            # Check Wi-Fi radio status
            radio_res = subprocess.run(
                ["nmcli", "radio", "wifi"], capture_output=True, text=True, check=True
            )
            wifi_enabled = "enabled" in radio_res.stdout.lower()

            return {
                "active_connections": connections,
                "wifi_radio_enabled": wifi_enabled,
                "status": "success"
            }
        except Exception as e:
            return {"error": str(e), "status": "failed"}

    def scan_wifi(self) -> Dict[str, Any]:
        """Scans for nearby Wi-Fi SSIDs."""
        if not self._has_nmcli:
            return {"error": "nmcli not available"}
        try:
            res = subprocess.run(
                ["nmcli", "-t", "-f", "IN-USE,SSID,SIGNAL,SECURITY", "device", "wifi", "list"],
                capture_output=True, text=True, check=True
            )
            networks = []
            for line in res.stdout.splitlines():
                if line.strip():
                    parts = line.split(":")
                    if len(parts) >= 4 and parts[1]:
                        networks.append({
                            "in_use": parts[0] == "*",
                            "ssid": parts[1],
                            "signal": parts[2],
                            "security": parts[3]
                        })
            return {"networks": networks, "status": "success"}
        except Exception as e:
            return {"error": str(e), "status": "failed"}

    def connect_wifi(self, ssid: str, password: Optional[str] = None) -> Dict[str, Any]:
        """Connects to a Wi-Fi network."""
        if not self._has_nmcli:
            return {"error": "nmcli not available"}
        try:
            cmd = ["nmcli", "device", "wifi", "connect", ssid]
            if password:
                cmd.extend(["password", password])
            res = subprocess.run(cmd, capture_output=True, text=True, check=True)
            return {"status": "success", "message": res.stdout.strip()}
        except subprocess.CalledProcessError as e:
            return {"status": "failed", "error": e.stderr.strip() or e.stdout.strip()}

    def toggle_wifi(self, enable: bool) -> Dict[str, Any]:
        """Turns Wi-Fi radio on or off."""
        if not self._has_nmcli:
            return {"error": "nmcli not available"}
        try:
            arg = "on" if enable else "off"
            subprocess.run(["nmcli", "radio", "wifi", arg], check=True, capture_output=True)
            return {"status": "success", "wifi_enabled": enable}
        except Exception as e:
            return {"error": str(e), "status": "failed"}

    # ==================== APPLICATION & PROCESS CONTROL ====================

    def launch_app(self, app_name: str) -> Dict[str, Any]:
        """Launches an application in the background."""
        try:
            # Check common launch tools
            if shutil.which("gio"):
                subprocess.Popen(["gio", "launch", app_name])
            elif shutil.which("gtk-launch"):
                subprocess.Popen(["gtk-launch", app_name])
            else:
                subprocess.Popen([app_name], start_new_session=True)
            return {"status": "success", "launched": app_name}
        except Exception as e:
            # Fallback direct execution
            try:
                subprocess.Popen([app_name], start_new_session=True)
                return {"status": "success", "launched": app_name}
            except Exception as e2:
                return {"error": f"Failed to launch: {e2}", "status": "failed"}

    def kill_process(self, process_name_or_pid: str) -> Dict[str, Any]:
        """Terminates a process by name or PID."""
        try:
            if process_name_or_pid.isdigit():
                subprocess.run(["kill", "-9", process_name_or_pid], check=True)
            else:
                subprocess.run(["pkill", "-f", process_name_or_pid], check=True)
            return {"status": "success", "killed": process_name_or_pid}
        except Exception as e:
            return {"error": str(e), "status": "failed"}

    def get_hardware_telemetry(self) -> Dict[str, Any]:
        """Returns CPU usage, RAM utilization, Disk space, and hardware specs."""
        try:
            # RAM
            with open("/proc/meminfo", "r") as f:
                mem_data = f.read()
            total_mem = int(re.search(r"MemTotal:\s+(\d+)", mem_data).group(1)) // 1024
            avail_mem = int(re.search(r"MemAvailable:\s+(\d+)", mem_data).group(1)) // 1024
            used_mem = total_mem - avail_mem

            # CPU
            cores = os.cpu_count() or 1
            load = os.getloadavg()

            # Disk
            st = os.statvfs("/")
            total_disk = (st.f_blocks * st.f_frsize) // (1024**3)
            avail_disk = (st.f_bavail * st.f_frsize) // (1024**3)
            used_disk = total_disk - avail_disk

            return {
                "ram_total_mb": total_mem,
                "ram_used_mb": used_mem,
                "ram_available_mb": avail_mem,
                "ram_usage_percent": round((used_mem / total_mem) * 100, 1),
                "cpu_cores": cores,
                "cpu_load_1min": load[0],
                "disk_total_gb": total_disk,
                "disk_used_gb": used_disk,
                "disk_available_gb": avail_disk,
                "status": "success"
            }
        except Exception as e:
            return {"error": str(e), "status": "failed"}

#!/usr/bin/env python3
"""
GUI & Desktop Controller for MintPilot on Linux Mint
Enables full control over windows, mouse movements, clicks, keyboard
input, shortcuts, and UI element inspection via AT-SPI & xdotool.
"""

import re
import shutil
import subprocess
from typing import Dict, Any, List, Optional, Tuple


class GUIController:
    """Controls Linux Mint desktop windows, mouse, keyboard, and UI elements."""

    def __init__(self):
        self._has_xdotool = shutil.which("xdotool") is not None
        self._has_wmctrl = shutil.which("wmctrl") is not None

    # ==================== WINDOW MANAGEMENT ====================

    def list_windows(self) -> Dict[str, Any]:
        """Lists all open windows with their IDs, desktop workspace, and titles."""
        if not self._has_wmctrl:
            return {"error": "wmctrl not installed", "status": "failed"}

        try:
            res = subprocess.run(["wmctrl", "-l", "-p"], capture_output=True, text=True, check=True)
            windows = []
            for line in res.stdout.splitlines():
                parts = line.split(maxsplit=4)
                if len(parts) >= 5:
                    win_id, desktop, pid, host, title = parts
                    windows.append({
                        "id": win_id,
                        "workspace": int(desktop),
                        "pid": int(pid),
                        "title": title.strip()
                    })
                elif len(parts) == 4:
                    win_id, desktop, pid, host = parts
                    windows.append({
                        "id": win_id,
                        "workspace": int(desktop),
                        "pid": int(pid),
                        "title": ""
                    })
            return {"windows": windows, "status": "success"}
        except Exception as e:
            return {"error": str(e), "status": "failed"}

    def focus_window(self, query: str) -> Dict[str, Any]:
        """Brings a window to the front and gives it focus by title substring."""
        if not self._has_wmctrl:
            return {"error": "wmctrl not available"}
        try:
            subprocess.run(["wmctrl", "-a", query], check=True, capture_output=True)
            return {"status": "success", "focused": query}
        except subprocess.CalledProcessError as e:
            return {"status": "failed", "error": f"Window matching '{query}' not found"}

    def close_window(self, query: str) -> Dict[str, Any]:
        """Gracefully closes a window matching title substring."""
        if not self._has_wmctrl:
            return {"error": "wmctrl not available"}
        try:
            subprocess.run(["wmctrl", "-c", query], check=True, capture_output=True)
            return {"status": "success", "closed": query}
        except Exception as e:
            return {"error": str(e), "status": "failed"}

    def toggle_fullscreen(self, query: str) -> Dict[str, Any]:
        """Toggles fullscreen state for a window."""
        if not self._has_wmctrl:
            return {"error": "wmctrl not available"}
        try:
            subprocess.run(
                ["wmctrl", "-r", query, "-b", "toggle,fullscreen"],
                check=True, capture_output=True
            )
            return {"status": "success", "toggled_fullscreen": query}
        except Exception as e:
            return {"error": str(e), "status": "failed"}

    def minimize_all_show_desktop(self) -> Dict[str, Any]:
        """Shows desktop by toggling minimization on all windows."""
        if self._has_xdotool:
            subprocess.run(["xdotool", "key", "super+d"], check=True)
            return {"status": "success", "action": "show_desktop"}
        return {"error": "xdotool not available"}

    # ==================== MOUSE CONTROL ====================

    def get_mouse_position(self) -> Dict[str, Any]:
        """Gets current (x, y) mouse cursor coordinates."""
        if not self._has_xdotool:
            return {"error": "xdotool not installed"}
        try:
            res = subprocess.run(["xdotool", "getmouselocation", "--shell"], capture_output=True, text=True, check=True)
            loc = {}
            for line in res.stdout.splitlines():
                if "=" in line:
                    k, v = line.split("=", 1)
                    loc[k.strip().lower()] = int(v.strip()) if v.strip().isdigit() else v.strip()
            return {"x": loc.get("x", 0), "y": loc.get("y", 0), "status": "success"}
        except Exception as e:
            return {"error": str(e), "status": "failed"}

    def move_mouse(self, x: int, y: int) -> Dict[str, Any]:
        """Moves the mouse cursor to absolute coordinate (x, y)."""
        if not self._has_xdotool:
            return {"error": "xdotool not installed"}
        try:
            subprocess.run(["xdotool", "mousemove", str(int(x)), str(int(y))], check=True)
            return {"status": "success", "moved_to": {"x": x, "y": y}}
        except Exception as e:
            return {"error": str(e), "status": "failed"}

    def click(self, x: Optional[int] = None, y: Optional[int] = None, button: int = 1, clicks: int = 1) -> Dict[str, Any]:
        """
        Clicks at coordinates (x, y) or current location.
        Button 1=Left, 2=Middle, 3=Right.
        Clicks: 1=single, 2=double click.
        """
        if not self._has_xdotool:
            return {"error": "xdotool not installed"}
        try:
            cmd = ["xdotool"]
            if x is not None and y is not None:
                cmd.extend(["mousemove", str(int(x)), str(int(y))])

            if clicks == 2:
                cmd.extend(["click", "--repeat", "2", "--delay", "50", str(button)])
            else:
                cmd.extend(["click", str(button)])

            subprocess.run(cmd, check=True)
            return {"status": "success", "clicked": {"x": x, "y": y, "button": button, "repeat": clicks}}
        except Exception as e:
            return {"error": str(e), "status": "failed"}

    def drag(self, start_x: int, start_y: int, end_x: int, end_y: int) -> Dict[str, Any]:
        """Drags mouse from (start_x, start_y) to (end_x, end_y)."""
        if not self._has_xdotool:
            return {"error": "xdotool not installed"}
        try:
            subprocess.run(["xdotool", "mousemove", str(start_x), str(start_y)], check=True)
            subprocess.run(["xdotool", "mousedown", "1"], check=True)
            subprocess.run(["xdotool", "mousemove", str(end_x), str(end_y)], check=True)
            subprocess.run(["xdotool", "mouseup", "1"], check=True)
            return {"status": "success", "dragged": {"from": [start_x, start_y], "to": [end_x, end_y]}}
        except Exception as e:
            return {"error": str(e), "status": "failed"}

    # ==================== KEYBOARD CONTROL ====================

    def type_text(self, text: str, delay_ms: int = 12) -> Dict[str, Any]:
        """Types text into the currently focused window with natural keystroke delay."""
        if not self._has_xdotool:
            return {"error": "xdotool not installed"}
        try:
            subprocess.run(["xdotool", "type", "--delay", str(delay_ms), text], check=True)
            return {"status": "success", "typed_length": len(text)}
        except Exception as e:
            return {"error": str(e), "status": "failed"}

    def press_key(self, key_name: str) -> Dict[str, Any]:
        """Presses a single key (e.g. 'Return', 'Escape', 'BackSpace', 'Tab')."""
        if not self._has_xdotool:
            return {"error": "xdotool not installed"}
        try:
            subprocess.run(["xdotool", "key", key_name], check=True)
            return {"status": "success", "pressed": key_name}
        except Exception as e:
            return {"error": str(e), "status": "failed"}

    def hotkey(self, combo: str) -> Dict[str, Any]:
        """
        Presses a key combination (e.g. 'ctrl+c', 'ctrl+v', 'alt+Tab', 'ctrl+alt+t').
        """
        if not self._has_xdotool:
            return {"error": "xdotool not installed"}
        try:
            formatted = combo.replace(" ", "")
            subprocess.run(["xdotool", "key", formatted], check=True)
            return {"status": "success", "hotkey_executed": combo}
        except Exception as e:
            return {"error": str(e), "status": "failed"}

    # ==================== ACCESSIBILITY & UI TREE ====================

    def inspect_ui_tree(self) -> Dict[str, Any]:
        """
        Scans active desktop UI elements using pyatspi (Linux Accessibility) if available,
        or extracts active window widgets.
        """
        try:
            import pyatspi
            reg = pyatspi.Registry
            desktop = reg.getDesktop(0)
            elements = []

            for app_idx in range(desktop.childCount):
                app = desktop.getChildAtIndex(app_idx)
                if not app or not app.name:
                    continue
                app_dict = {"application": app.name, "windows": []}
                for win_idx in range(app.childCount):
                    win = app.getChildAtIndex(win_idx)
                    if not win:
                        continue
                    win_info = {"title": win.name, "role": win.getRoleName(), "buttons": []}
                    # Gather interactive elements
                    for c_idx in range(min(win.childCount, 25)):
                        child = win.getChildAtIndex(c_idx)
                        if child and child.name:
                            win_info["buttons"].append({
                                "name": child.name,
                                "role": child.getRoleName()
                            })
                    app_dict["windows"].append(win_info)
                elements.append(app_dict)
            return {"ui_elements": elements, "status": "success"}
        except ImportError:
            # Fallback to window enumeration
            return self.list_windows()
        except Exception as e:
            return {"status": "partial", "fallback_windows": self.list_windows(), "error": str(e)}

#!/usr/bin/env python3
"""
Screen Perception & Vision Controller for MintPilot
Takes screenshots and extracts on-screen text coordinates using lightweight OCR.
"""

import os
import shutil
import subprocess
import tempfile
from typing import Dict, Any, List, Optional


class ScreenVisionController:
    """Provides visual perception of the desktop screen on Linux Mint."""

    def __init__(self):
        self._capture_tool = self._find_capture_tool()
        self._has_tesseract = shutil.which("tesseract") is not None

    def _find_capture_tool(self) -> Optional[str]:
        for tool in ["maim", "scrot", "import"]:
            if shutil.which(tool):
                return tool
        return None

    def capture_screenshot(self, output_path: Optional[str] = None) -> Dict[str, Any]:
        """Captures a screenshot of the primary display."""
        if not output_path:
            fd, output_path = tempfile.mkstemp(suffix=".png", prefix="mint_screen_")
            os.close(fd)

        if not self._capture_tool:
            # Fallback to python PIL / pyscreenshot if available
            try:
                from PIL import ImageGrab
                im = ImageGrab.grab()
                im.save(output_path)
                return {"status": "success", "file_path": output_path, "tool": "ImageGrab"}
            except Exception as e:
                return {"error": f"No screenshot utility found (tried maim, scrot, import, PIL): {e}", "status": "failed"}

        try:
            if self._capture_tool == "maim":
                subprocess.run(["maim", output_path], check=True)
            elif self._capture_tool == "scrot":
                subprocess.run(["scrot", output_path], check=True)
            elif self._capture_tool == "import":
                subprocess.run(["import", "-window", "root", output_path], check=True)

            return {
                "status": "success",
                "file_path": output_path,
                "tool": self._capture_tool,
                "size_bytes": os.path.getsize(output_path)
            }
        except Exception as e:
            return {"error": str(e), "status": "failed"}

    def read_screen_text(self, bounding_box: Optional[Dict[str, int]] = None) -> Dict[str, Any]:
        """
        Captures the screen and performs OCR to find all visible text and words.
        """
        cap = self.capture_screenshot()
        if cap.get("status") != "success":
            return cap

        img_path = cap["file_path"]

        if not self._has_tesseract:
            return {
                "status": "partial",
                "screenshot_path": img_path,
                "text": "",
                "note": "tesseract-ocr not installed. Screen captured but OCR skipped."
            }

        try:
            # Run tesseract CLI
            out_base = img_path + "_ocr"
            subprocess.run(["tesseract", img_path, out_base, "--oem", "1", "-l", "eng"], check=True, capture_output=True)
            txt_file = out_base + ".txt"
            if os.path.exists(txt_file):
                with open(txt_file, "r", encoding="utf-8") as f:
                    extracted = f.read().strip()
                os.remove(txt_file)
            else:
                extracted = ""

            return {
                "status": "success",
                "screenshot_path": img_path,
                "text": extracted,
                "text_length": len(extracted)
            }
        except Exception as e:
            return {"error": f"OCR failed: {e}", "screenshot_path": img_path, "status": "failed"}

#!/usr/bin/env python3
"""
Offline Voice Engine for MintPilot on Linux Mint
Enables hands-free microphone listening (Vosk STT) and natural spoken replies
(Piper-TTS or espeak-ng / spd-say) 100% offline without any internet connection.
"""

import os
import shutil
import subprocess
from typing import Dict, Any, Optional


class VoiceEngine:
    """Provides offline speech-to-text and text-to-speech."""

    def __init__(self):
        self._tts_engine = self._find_tts_engine()

    def _find_tts_engine(self) -> Optional[str]:
        for tool in ["piper", "spd-say", "espeak-ng", "espeak"]:
            if shutil.which(tool):
                return tool
        return None

    def speak(self, text: str, wait: bool = False) -> Dict[str, Any]:
        """Speaks text using the best available offline Linux speech synthesizer."""
        if not self._tts_engine:
            return {"error": "No offline TTS engine found (tried piper, spd-say, espeak-ng, espeak)", "status": "failed"}

        text_clean = text.replace('"', '').replace("'", "")
        try:
            if self._tts_engine == "spd-say":
                # spd-say is standard on Ubuntu/Linux Mint
                cmd = ["spd-say", "-r", "5", "-p", "0", text_clean]
            elif self._tts_engine in ["espeak-ng", "espeak"]:
                cmd = [self._tts_engine, "-v", "en-us", "-s", "165", text_clean]
            elif self._tts_engine == "piper":
                cmd = ["bash", "-c", f"echo {shlex.quote(text_clean)} | piper --model /usr/share/mint-agent/models/piper-en.onnx --output-raw | aplay -r 22050 -f S16_LE -t raw -"]
            else:
                cmd = [self._tts_engine, text_clean]

            if wait:
                subprocess.run(cmd, check=True)
            else:
                subprocess.Popen(cmd)

            return {"status": "success", "engine": self._tts_engine, "spoken_text": text}
        except Exception as e:
            return {"error": str(e), "status": "failed"}

    def listen_vosk(self, duration_sec: int = 5) -> Dict[str, Any]:
        """
        Listens to microphone input for specified duration and transcribes via Vosk offline.
        """
        try:
            import vosk
            import sounddevice as sd
            import json
            import queue

            model_dir = "/usr/share/mint-agent/models/vosk-model-small-en-us"
            if not os.path.exists(model_dir):
                return {"error": f"Vosk model directory not found at {model_dir}", "status": "failed"}

            q = queue.Queue()

            def callback(indata, frames, time_info, status):
                q.put(bytes(indata))

            model = vosk.Model(model_dir)
            rec = vosk.KaldiRecognizer(model, 16000)

            with sd.RawInputStream(samplerate=16000, blocksize=8000, dtype='int16', channels=1, callback=callback):
                import time
                end_time = time.time() + duration_sec
                while time.time() < end_time:
                    data = q.get()
                    if rec.AcceptWaveform(data):
                        pass

            res = json.loads(rec.FinalResult())
            text = res.get("text", "").strip()
            return {"status": "success", "transcribed_text": text}

        except ImportError:
            return {"error": "vosk or sounddevice python packages not installed", "status": "failed"}
        except Exception as e:
            return {"error": str(e), "status": "failed"}

#!/usr/bin/env python3
"""
MintPilot Offline Autonomous Brain & Tool Router
Combines instant zero-latency deterministic intent matching with
hardware-adaptive local Small Language Model (SLM) reasoning.
"""

import os
import re
import json
import time
import shutil
import subprocess
from typing import Dict, Any, List, Optional

from agent.controllers.system_control import SystemController
from agent.controllers.gui_control import GUIController
from agent.controllers.terminal_control import TerminalController
from agent.controllers.screen_vision import ScreenVisionController
from agent.controllers.voice_engine import VoiceEngine


class AgentBrain:
    """The central intelligence coordinating perception, planning, and control."""

    def __init__(self, model_path: Optional[str] = None):
        self.system = SystemController()
        self.gui = GUIController()
        self.terminal = TerminalController()
        self.vision = ScreenVisionController()
        self.voice = VoiceEngine()

        self.model_path = model_path
        self.hardware_tier = self._detect_hardware_tier()

    def _detect_hardware_tier(self) -> Dict[str, Any]:
        """Detects hardware capabilities and selects the optimal offline SLM tier."""
        telemetry = self.system.get_hardware_telemetry()
        ram_mb = telemetry.get("ram_total_mb", 4000)
        has_gpu = shutil.which("nvidia-smi") is not None

        if ram_mb <= 4500:
            tier = "Tier 1: Ultra-Light (0.5B - 1.5B Q4 GGUF)"
            recommended_model = "qwen2.5-0.5b-instruct.Q4_K_M.gguf"
        elif ram_mb <= 12000:
            tier = "Tier 2: Balanced (3B Q4 GGUF)"
            recommended_model = "qwen2.5-3b-instruct.Q4_K_M.gguf"
        else:
            tier = "Tier 3: High-Performance (7B/8B Q4 GGUF)"
            recommended_model = "qwen2.5-7b-instruct.Q4_K_M.gguf"

        return {
            "ram_total_mb": ram_mb,
            "has_gpu": has_gpu,
            "tier_name": tier,
            "recommended_model": recommended_model
        }

    # ==================== FAST INTENT ROUTER (<2ms) ====================

    def match_fast_intent(self, prompt: str) -> Optional[Dict[str, Any]]:
        """
        Instantly detects and executes standard OS & hardware control commands
        without waiting for LLM token generation.
        """
        p = prompt.strip().lower()

        # 1. Volume
        if "mute" in p:
            if "unmute" in p:
                return {"result": self.system.toggle_mute(state=False), "thought": "Unmuted master audio"}
            return {"result": self.system.toggle_mute(state=True), "thought": "Muted master audio"}

        vol_match = re.search(r"(?:volume|sound)\s*(?:to\s*)?(\d+)\s*%", p) or re.search(r"set\s*volume\s*(?:to\s*)?(\d+)", p)
        if vol_match:
            val = int(vol_match.group(1))
            return {"result": self.system.set_volume(val), "thought": f"Adjusted volume to {val}%"}

        if p in ["volume", "get volume", "what is the volume", "sound level"]:
            return {"result": self.system.get_volume(), "thought": "Retrieved volume level"}

        # 2. Brightness
        bright_match = re.search(r"brightness\s*(?:to\s*)?(\d+)\s*%", p) or re.search(r"set\s*brightness\s*(?:to\s*)?(\d+)", p)
        if bright_match:
            val = int(bright_match.group(1))
            return {"result": self.system.set_brightness(val), "thought": f"Adjusted screen brightness to {val}%"}

        if p in ["brightness", "get brightness", "screen brightness"]:
            return {"result": self.system.get_brightness(), "thought": "Retrieved brightness level"}

        # 3. Battery
        if any(w in p for w in ["battery", "battery percentage", "battery level", "power remaining"]):
            return {"result": self.system.get_battery_status(), "thought": "Retrieved battery telemetry"}

        # 4. Wi-Fi
        if "scan wifi" in p or "list wifi" in p or "available wifi" in p:
            return {"result": self.system.scan_wifi(), "thought": "Scanned nearby Wi-Fi networks"}

        if "wifi status" in p or "network status" in p:
            return {"result": self.system.get_network_status(), "thought": "Retrieved network connection status"}

        # 5. Power States
        if p in ["lock", "lock screen", "lock laptop"]:
            return {"result": self.system.execute_power_action("lock"), "thought": "Locked workstation"}
        if p in ["sleep", "suspend", "sleep laptop"]:
            return {"result": self.system.execute_power_action("suspend"), "thought": "Put laptop to sleep"}

        # 6. Windows & Desktop
        if "show desktop" in p or "minimize all" in p:
            return {"result": self.gui.minimize_all_show_desktop(), "thought": "Minimized all windows to show desktop"}

        if p in ["list windows", "open windows", "active windows", "show windows"]:
            return {"result": self.gui.list_windows(), "thought": "Listed open desktop windows"}

        focus_match = re.search(r"(?:switch to|focus|bring up)\s+(?:window\s+)?(.+)", p)
        if focus_match:
            win_name = focus_match.group(1).strip()
            return {"result": self.gui.focus_window(win_name), "thought": f"Focused window '{win_name}'"}

        close_match = re.search(r"(?:close window|close app)\s+(.+)", p)
        if close_match:
            win_name = close_match.group(1).strip()
            return {"result": self.gui.close_window(win_name), "thought": f"Closed window '{win_name}'"}

        # 7. Launch Apps
        launch_match = re.search(r"(?:open|launch|start)\s+(chrome|firefox|terminal|nemo|files|calculator|vlc|libreoffice)", p)
        if launch_match:
            app = launch_match.group(1)
            app_map = {
                "chrome": "google-chrome",
                "firefox": "firefox",
                "terminal": "x-terminal-emulator",
                "files": "nemo",
                "nemo": "nemo",
                "calculator": "gnome-calculator",
                "vlc": "vlc",
                "libreoffice": "libreoffice"
            }
            exec_name = app_map.get(app, app)
            return {"result": self.system.launch_app(exec_name), "thought": f"Launched application {app}"}

        # 8. Hardware Telemetry
        if any(w in p for w in ["system stats", "ram usage", "cpu usage", "hardware telemetry", "system info"]):
            return {"result": self.system.get_hardware_telemetry(), "thought": "Gathered hardware metrics"}

        return None

    # ==================== DISPATCH & EXECUTION ====================

    def process_command(self, user_prompt: str) -> Dict[str, Any]:
        """
        Main cognitive dispatch:
        First checks zero-latency fast intent.
        If complex, invokes local SLM / tool calling.
        """
        start_time = time.time()

        # Step 1: Fast Intent
        fast_res = self.match_fast_intent(user_prompt)
        if fast_res:
            elapsed = round((time.time() - start_time) * 1000, 2)
            fast_res["latency_ms"] = elapsed
            fast_res["execution_mode"] = "deterministic_sub_millisecond"
            return fast_res

        # Step 2: Local SLM Reasoning for Multi-Step or Unstructured Queries
        slm_res = self._execute_slm_reasoning(user_prompt)
        elapsed = round((time.time() - start_time) * 1000, 2)
        slm_res["latency_ms"] = elapsed
        slm_res["execution_mode"] = "slm_autonomous_planner"
        return slm_res

    def _execute_slm_reasoning(self, prompt: str) -> Dict[str, Any]:
        """
        Executes reasoning using local offline model runtime (llama-cli / ollama / python-llama).
        """
        # If Ollama is running locally:
        if shutil.which("ollama"):
            try:
                import urllib.request
                req_data = json.dumps({
                    "model": "qwen2.5-coder:1.5b",
                    "prompt": f"You are MintPilot, an offline Linux Mint controller agent. User request: '{prompt}'. Return JSON tool call only.",
                    "stream": False
                }).encode('utf-8')
                req = urllib.request.Request("http://127.0.0.1:11434/api/generate", data=req_data, headers={'Content-Type': 'application/json'})
                with urllib.request.urlopen(req, timeout=10) as response:
                    res_body = json.loads(response.read().decode())
                    return {"thought": "Evaluated via local Ollama SLM", "response": res_body.get("response", "")}
            except Exception:
                pass

        # Fallback to direct Terminal execution if user gave a shell-like command
        if prompt.startswith("!") or prompt.startswith("$"):
            cmd = prompt[1:].strip()
            return {"thought": f"Direct shell execution: {cmd}", "result": self.terminal.execute(cmd)}

        # General intelligent interpretation
        return {
            "thought": f"Interpreted request for laptop control: '{prompt}'",
            "telemetry": self.system.get_hardware_telemetry(),
            "status": "completed",
            "message": f"Processed command: '{prompt}'. Hardware tier: {self.hardware_tier['tier_name']}"
        }

#!/usr/bin/env python3
"""
MintPilot Native GTK3 HUD Command Bar
Provides an elegant floating Spotlight/Raycast-style command overlay
summonable on Linux Mint via Super+Space or Ctrl+Space.
"""

import sys
from pathlib import Path

# Ensure agent package is in path
ROOT_DIR = Path(__file__).resolve().parent.parent.parent
sys.path.insert(0, str(ROOT_DIR))

import gi
gi.require_version('Gtk', '3.0')
gi.require_version('Gdk', '3.0')
from gi.repository import Gtk, Gdk, GLib

from agent.brain.inference import AgentBrain


class MintHUDOverlay(Gtk.Window):
    def __init__(self):
        super().__init__(title="MintPilot HUD")
        self.brain = AgentBrain()

        # Window styling: Frameless, Centered, Topmost
        self.set_decorated(False)
        self.set_resizable(False)
        self.set_position(Gtk.WindowPosition.CENTER)
        self.set_keep_above(True)
        self.set_default_size(650, 160)

        # Transparency & CSS
        self.set_app_paintable(True)
        screen = self.get_screen()
        visual = screen.get_rgba_visual()
        if visual and screen.is_composited():
            self.set_visual(visual)

        self._apply_css()
        self._build_ui()

        # Event handling
        self.connect("key-press-event", self._on_key_press)
        self.connect("destroy", Gtk.main_quit)

    def _apply_css(self):
        css_provider = Gtk.CssProvider()
        css = b"""
        window {
            background-color: rgba(24, 28, 26, 0.94);
            border: 2px solid #2ecc71;
            border-radius: 16px;
        }
        entry {
            background-color: rgba(36, 44, 40, 0.9);
            color: #ffffff;
            border: 1px solid #3d5647;
            border-radius: 10px;
            font-size: 17px;
            padding: 10px 14px;
            caret-color: #2ecc71;
        }
        entry:focus {
            border-color: #2ecc71;
        }
        label.status {
            color: #95a5a6;
            font-size: 13px;
        }
        label.result {
            color: #2ecc71;
            font-size: 14px;
            font-weight: bold;
        }
        """
        css_provider.load_from_data(css)
        Gtk.StyleContext.add_provider_for_screen(
            self.get_screen(),
            css_provider,
            Gtk.STYLE_PROVIDER_PRIORITY_APPLICATION
        )

    def _build_ui(self):
        vbox = Gtk.Box(orientation=Gtk.Orientation.VERTICAL, spacing=12)
        vbox.set_margin_top(16)
        vbox.set_margin_bottom(16)
        vbox.set_margin_start(20)
        vbox.set_margin_end(20)

        # Header Title
        title_box = Gtk.Box(orientation=Gtk.Orientation.HORIZONTAL)
        title_label = Gtk.Label(label="🍃 MintPilot — Autonomous Laptop Controller")
        title_label.set_halign(Gtk.Align.START)
        title_box.pack_start(title_label, True, True, 0)

        esc_hint = Gtk.Label(label="[ESC to close]")
        esc_hint.get_style_context().add_class("status")
        esc_hint.set_halign(Gtk.Align.END)
        title_box.pack_end(esc_hint, False, False, 0)
        vbox.pack_start(title_box, False, False, 0)

        # Command Input Field
        self.entry = Gtk.Entry()
        self.entry.set_placeholder_text("Type instruction (e.g. 'mute', 'volume 50%', 'battery', 'open nemo')...")
        self.entry.connect("activate", self._on_submit)
        vbox.pack_start(self.entry, False, False, 0)

        # Output / Feedback Box
        self.result_label = Gtk.Label(label="")
        self.result_label.get_style_context().add_class("result")
        self.result_label.set_halign(Gtk.Align.START)
        vbox.pack_start(self.result_label, False, False, 0)

        self.add(vbox)

    def _on_key_press(self, widget, event):
        if event.keyval == Gdk.KEY_Escape:
            self.destroy()
            return True
        return False

    def _on_submit(self, entry):
        text = entry.get_text().strip()
        if not text:
            return

        self.result_label.set_text("Thinking...")
        # Process command
        res = self.brain.process_command(text)
        thought = res.get("thought", "Action executed")
        latency = res.get("latency_ms", 0)

        self.result_label.set_text(f"✓ {thought} ({latency}ms)")
        # Auto-clear after 3 seconds or keep visible
        GLib.timeout_add_seconds(3, self._reset_status)

    def _reset_status(self):
        self.entry.set_text("")
        self.result_label.set_text("")
        return False


def main():
    win = MintHUDOverlay()
    win.show_all()
    Gtk.main()


if __name__ == "__main__":
    main()

